func newTenderOfferToken() unsafe.Pointer { return unsafe.Pointer(new(tender.TenderOfferToken)) }

func newNTenderOfferToken(n int) unsafe.Pointer {
	return unsafe.Pointer(unsafe.SliceData(make([]tender.TenderOfferToken, n)))
}

func ptrTenderOfferToken(p unsafe.Pointer, c int32) any {
	r := (*tender.TenderOfferToken)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 2:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 3:
		return (*string)(unsafe.Pointer(&r.TenderOfferID))
	case 4:
		return &r.TokenHash
	case 5:
		return &r.Email
	case 6:
		return &r.ExpiresAt
	case 7:
		return &r.UsedAt
	case 8:
		return &r.RevokedAt
	case 9:
		return &r.CreatedAt
	case 10:
		return &r.UpdatedAt
	}
	return nil
}

func valueTenderOfferToken(p unsafe.Pointer, c int32) any {
	r := (*tender.TenderOfferToken)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return string(r.OrganizationID)
	case 3:
		return string(r.TenderOfferID)
	case 4:
		return r.TokenHash
	case 5:
		return r.Email
	case 6:
		return r.ExpiresAt
	case 7:
		if r.UsedAt == nil {
			return nil
		}
		return *r.UsedAt
	case 8:
		if r.RevokedAt == nil {
			return nil
		}
		return *r.RevokedAt
	case 9:
		return r.CreatedAt
	case 10:
		return r.UpdatedAt
	}
	return nil
}

func attachTenderOfferToken(p unsafe.Pointer, rel int32, child unsafe.Pointer) {
	r := (*tender.TenderOfferToken)(p)
	switch rel {
	case 0:
		r.TenderOffer = (*tender.TenderOffer)(child)
	}
}

